const KEY='ritim-v2',OLD_KEY='ritim-v1';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Istanbul'}).format(new Date()),parse=d=>new Date(d+'T12:00:00'),dateKey=d=>`${String(d.getFullYear()).padStart(4,'0')}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,addDays=(d,n)=>{const x=parse(d);x.setDate(x.getDate()+n);return dateKey(x)},uid=()=>crypto.randomUUID();
const base=['Spor','Kitap okuma','İngilizce çalışma','Film izleme','Yazılım öğrenme','Proje geliştirme'];
function freshState(){return {version:2,categories:base.map((name,id)=>({id:String(id),name,goal:'',rules:[{from:today(),days:[0,1,2,3,4,5,6],checkpoints:[]}]})),days:{}}}
// Preserve saved plans; application updates never reset browser data.
let state;
try{state=JSON.parse(localStorage.getItem(KEY))}catch{}
if(!state)state=freshState();
let activeStorageKey=KEY;
let selected=today(),month=selected.slice(0,7),view='today';
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3000)}
function save(){try{localStorage.setItem(activeStorageKey,JSON.stringify(state));globalThis.ritimSaved?.();return true}catch{toast('Değişiklik kaydedilemedi. Depolama alanını kontrol et.');return false}}
function change(fn){const old=structuredClone(state);fn();if(!save())state=old;render()}
const category=id=>state.categories.find(c=>c.id===String(id));
function ruleFor(c,d){return [...c.rules].reverse().find(r=>r.from<=d)}
function buildDay(d){return {entries:state.categories.flatMap(c=>{const r=ruleFor(c,d);return r?.days.includes(parse(d).getDay())?[{id:uid(),category:c.id,name:c.name,status:'planned',checkpoints:r.checkpoints.map(text=>({id:uid(),text,done:false}))}]:[]})}}
function dayFor(d){return state.days[d]||buildDay(d)}
function ensureDay(d){return state.days[d]??=buildDay(d)}
function entry(id){return ensureDay(selected).entries.find(e=>e.id===id)}
const done=e=>e.status==='done'||(e.checkpoints.length>0&&e.checkpoints.every(p=>p.done)),percent=es=>es.length?Math.round(es.filter(done).length/es.length*100):0;
function stats(es){return `<div class="stats"><div class="stat"><div><small>Tamamlanan kategori</small><strong>${es.filter(done).length}<em> / ${es.length}</em></strong></div></div><div class="stat"><div><small>Checkpoint</small><strong>${es.flatMap(e=>e.checkpoints).filter(p=>p.done).length}<em> / ${es.flatMap(e=>e.checkpoints).length}</em></strong></div></div><div class="stat"><div><small>Plana uyum</small><strong>%${percent(es)}</strong></div></div></div>`}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const titles={today:['Günlük plan','Kategorilerini ve küçük adımlarını takip et.'],calendar:['Takvim','İstediğin güne git, planını oluştur.'],categories:['Kategoriler','Varsayılan checkpointleri ve tekrar günlerini belirle.'],progress:['İlerleme','Bu ayki günlük plan ve checkpoint performansın.']};$('#heading').textContent=titles[view][0];$('#subtitle').textContent=titles[view][1];$('#add').textContent=view==='categories'?'+ Kategori ekle':'+ Güne kategori ekle';if(view==='today')renderToday();if(view==='calendar')renderCalendar();if(view==='categories')renderCategories();if(view==='progress')renderProgress()}
function entryHTML(e){return `<article class="daily-category ${done(e)?'category-complete':''}"><div class="section-head"><div><h2>${esc(e.name)}</h2><p class="note">${done(e)?'Tamamlandı':e.status==='missed'?'Kaçırıldı':e.checkpoints.length?`${e.checkpoints.filter(p=>p.done).length} / ${e.checkpoints.length} checkpoint`:'Checkpoint ekleyebilir veya kategoriyi tamamlayabilirsin.'}</p></div><button class="check ${done(e)?'is-done':''}" data-action="complete" aria-pressed="${done(e)}" data-entry="${e.id}" aria-label="${esc(e.name)}: ${done(e)?'tamamlamayı geri al':'tamamla'}">${done(e)?'✓':''}</button></div><div>${e.checkpoints.map(p=>`<div class="checkpoint ${p.done?'checkpoint-complete':''}"><label><input type="checkbox" data-check="${p.id}" data-entry="${e.id}" ${p.done?'checked':''}><span class="${p.done?'checked-text':''}">${esc(p.text)}${p.note?`<small>${esc(p.note)}</small>`:''}${p.legacyStatus==='missed'?'<small>Önceki kayıt: kaçırıldı</small>':''}</span></label><button data-action="remove-check" data-entry="${e.id}" data-check="${p.id}" aria-label="Checkpointi kaldır">×</button></div>`).join('')}</div><details class="task-options checkpoint-adder"><summary>Checkpoint ekle</summary><form class="inline-form" data-add-check="${e.id}"><input name="text" required maxlength="200" placeholder="Bu güne checkpoint ekle" aria-label="${esc(e.name)} için yeni checkpoint"><button>Ekle</button></form></details><details class="task-options"><summary>İşlemler</summary><div class="actions"><button data-action="missed" data-entry="${e.id}">${e.status==='missed'?'Kaçırıldı işaretini kaldır':'Kaçırdım'}</button><button data-action="remove-entry" data-entry="${e.id}">Bu günden kaldır</button></div></details></article>`}
function renderToday(){if(!state.days[selected]){const old=structuredClone(state);ensureDay(selected);if(!save()){state=old;$('#content').innerHTML='<p role="alert">Gün açılamadı: tarayıcı depolamasına erişilemiyor. Yedek alıp tekrar dene.</p>';return}}const es=state.days[selected].entries,mon=addDays(selected,-((parse(selected).getDay()+6)%7));$('#content').innerHTML=`${stats(es)}<section><div class="section-head"><h2>${parse(selected).toLocaleDateString('tr-TR',{day:'numeric',month:'long',year:'numeric'})}</h2><div class="date-nav"><button data-shift="-1" aria-label="Önceki gün">‹</button><input id="selectedDate" type="date" value="${selected}" aria-label="Gün seç"><button data-shift="1" aria-label="Sonraki gün">›</button><button id="goToday">Bugün</button></div></div><div class="week">${Array.from({length:7},(_,i)=>{const d=addDays(mon,i);return `<button data-date="${d}" class="${d===selected?'selected':''}"><small>${parse(d).toLocaleDateString('tr-TR',{weekday:'short'})}</small><b>${parse(d).getDate()}</b></button>`}).join('')}</div>${es.length?es.map(entryHTML).join(''):'<div class="empty"><strong>Bu gün için kategori yok.</strong>Kategori ekleyebilir veya Kategoriler sayfasından tekrar günleri belirleyebilirsin.</div>'}<button id="addDayCategory" class="wide">+ Bu güne kategori ekle</button><p class="note">Günlük eklemeler yalnızca bu güne aittir. Varsayılanlar, yeni oluşturulan günlere uygulanır.</p></section>`}
function renderCalendar(){const first=month+'-01',offset=(parse(first).getDay()+6)%7,count=new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate();$('#content').innerHTML=`<section class="panel"><div class="section-head"><h2>${parse(first).toLocaleDateString('tr-TR',{month:'long',year:'numeric'})}</h2><div class="date-nav"><button data-month="-1" aria-label="Önceki ay">‹</button><input id="monthSelect" type="month" value="${month}" aria-label="Ay seç"><button data-month="1" aria-label="Sonraki ay">›</button><button id="goToday">Bugün</button></div></div><div class="calendar">${['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'].map(d=>`<p class="note">${d}</p>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:count},(_,i)=>{const d=month+'-'+String(i+1).padStart(2,'0'),es=dayFor(d).entries;return `<button class="day ${d===selected?'selected':''}" data-date="${d}"><b>${i+1}</b>${es.length?`<small>${es.length} kategori</small><div class="bar"><i style="width:${percent(es)}%"></i></div>`:''}</button>`}).join('')}</div></section>`}
const weekNames=['Pazar','Pazartesi','Salı','Çarşamba','Perşembe','Cuma','Cumartesi'];
const presets={daily:[0,1,2,3,4,5,6],weekdays:[1,2,3,4,5],weekend:[0,6],saturday:[6],sunday:[0],manual:[]};
function applyCategoryUpdate(id,update,scope){
 const c=category(id),from=scope==='all'?'0001-01-01':today();
 c.name=update.name;c.goal=update.goal;
 const rule={from,days:[...update.days],checkpoints:[...update.checkpoints]};
 c.rules=scope==='all'?[rule]:[...c.rules.filter(r=>r.from<from),rule];
 for(const [date,day] of Object.entries(state.days)){
  if(date<from)continue;
  const matches=rule.days.includes(parse(date).getDay()),entries=day.entries.filter(e=>e.category===c.id);
  if(!matches){day.entries=day.entries.filter(e=>e.category!==c.id);continue}
  if(!entries.length){day.entries.push({id:uid(),category:c.id,name:c.name,status:'planned',checkpoints:rule.checkpoints.map(text=>({id:uid(),text,done:false}))});continue}
  for(const en of entries){const remaining=[...en.checkpoints];const wasDone=done(en);en.name=c.name;en.checkpoints=rule.checkpoints.map(text=>{const i=remaining.findIndex(p=>p.text===text);return i<0?{id:uid(),text,done:false}:remaining.splice(i,1)[0]});en.status=en.checkpoints.length?(en.checkpoints.every(p=>p.done)?'done':'planned'):(wasDone?'done':'planned')}
 }
}
function renderCategories(){$('#content').innerHTML=`<p class="note">Değişikliklerin hangi günlere uygulanacağını seç. Seçilen günlerde checkpoint listesi güncellenir; aynı adlı checkpointlerin işaretleri korunur.</p><div class="category-grid">${state.categories.map(c=>{const r=ruleFor(c,today())||c.rules.at(-1);return `<form class="panel category-editor" data-category="${esc(c.id)}"><label>Kategori adı<input name="name" value="${esc(c.name)}" maxlength="80" required></label><label>Hedef<input name="goal" value="${esc(c.goal)}" maxlength="250" placeholder="İsteğe bağlı"></label><label>Günlere ata<select class="preset" aria-label="${esc(c.name)} gün atama"><option value="custom">Günleri seç</option><option value="daily">Her güne ekle</option><option value="weekdays">Sadece hafta içi</option><option value="weekend">Sadece hafta sonu</option><option value="saturday">Sadece cumartesi</option><option value="sunday">Sadece pazar</option><option value="manual">Otomatik ekleme</option></select></label><div class="day-choices">${[1,2,3,4,5,6,0].map(d=>`<label><input type="checkbox" name="days" value="${d}" ${r.days.includes(d)?'checked':''}><span>${weekNames[d]}</span></label>`).join('')}</div><label>Varsayılan checkpointler<textarea name="checkpoints" rows="4" placeholder="Her satıra bir checkpoint yaz">${esc(r.checkpoints.join('\n'))}</textarea></label><label>Uygulama kapsamı<select name="applyScope"><option value="future">Bugünden sonrasına uygula</option><option value="all">Tüm günlerin üzerine uygula</option></select></label><p class="note">İlk seçenek bugün dahil sonraki günleri günceller. Gün ataması kaldırılan tarihlerden kategori çıkarılır. Checkpoint listesi yeni listeyle değiştirilir.</p><button class="primary wide">Değişiklikleri kaydet</button></form>`}).join('')}</div>`}
function openCategory(){ $('#categoryForm').reset();$('#categoryDialog').showModal() }
function openDayCategory(){const available=state.categories.filter(c=>!ensureDay(selected).entries.some(e=>e.category===c.id));if(!available.length){toast('Tüm kategoriler bu günde mevcut. Yeni kategori ekleyebilirsin.');return}$('#dayCategorySelect').innerHTML=available.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');$('#dayDialog').showModal()}
$('#add').onclick=()=>view==='categories'?openCategory():openDayCategory();document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});
$('#categoryForm').onsubmit=e=>{e.preventDefault();const name=e.target.elements.name.value.trim();if(!name)return;if(state.categories.some(c=>c.name.toLocaleLowerCase('tr')===name.toLocaleLowerCase('tr'))){toast('Bu isimde kategori zaten var.');return}change(()=>state.categories.push({id:uid(),name,goal:'',rules:[{from:today(),days:[],checkpoints:[]}]}));$('#categoryDialog').close();view='categories';render();toast('Kategori eklendi. Günleri ve checkpointleri belirleyebilirsin.')};
$('#dayForm').onsubmit=e=>{e.preventDefault();const c=category($('#dayCategorySelect').value),r=ruleFor(c,selected)||c.rules.at(-1);change(()=>ensureDay(selected).entries.push({id:uid(),category:c.id,name:c.name,status:'planned',checkpoints:r.checkpoints.map(text=>({id:uid(),text,done:false}))}));$('#dayDialog').close();view='today';render()};
 document.addEventListener('submit',e=>{const f=e.target;if(f.dataset.addCheck){e.preventDefault();const text=f.elements.text.value.trim();if(text)change(()=>{const en=entry(f.dataset.addCheck);en.checkpoints.push({id:uid(),text,done:false});en.status='planned'})}if(f.dataset.category){e.preventDefault();const name=f.elements.name.value.trim();if(!name)return;if(state.categories.some(c=>c.id!==f.dataset.category&&c.name.toLocaleLowerCase('tr')===name.toLocaleLowerCase('tr'))){toast('Bu isimde kategori zaten var.');return}change(()=>applyCategoryUpdate(f.dataset.category,{name,goal:f.elements.goal.value.trim(),days:[...f.querySelectorAll('input[name="days"]:checked')].map(x=>Number(x.value)),checkpoints:f.elements.checkpoints.value.split('\n').map(s=>s.trim()).filter(Boolean)},f.elements.applyScope.value));toast('Kategori seçilen günlere uygulandı.')}});
 document.addEventListener('change',e=>{const el=e.target;if(el.id==='selectedDate'&&el.value){selected=el.value;month=selected.slice(0,7);render()}if(el.id==='monthSelect'&&el.value){month=el.value;render()}if(el.matches('.preset')&&el.value!=='custom'){const days=presets[el.value];el.closest('form').querySelectorAll('input[name="days"]').forEach(x=>x.checked=days.includes(Number(x.value)))}if(el.dataset.check&&el.type==='checkbox')change(()=>{const en=entry(el.dataset.entry);en.checkpoints.find(p=>p.id===el.dataset.check).done=el.checked;en.status='planned'})});
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.close){$(b.dataset.close).close();return}if(b.dataset.date){selected=b.dataset.date;month=selected.slice(0,7);view='today';render()}if(b.dataset.shift){selected=addDays(selected,Number(b.dataset.shift));month=selected.slice(0,7);render()}if(b.dataset.month){const d=parse(month+'-01');d.setMonth(d.getMonth()+Number(b.dataset.month));month=dateKey(d).slice(0,7);render()}if(b.id==='goToday'){selected=today();month=selected.slice(0,7);render()}if(b.id==='addDayCategory')openDayCategory();if(b.dataset.action){change(()=>{const en=entry(b.dataset.entry);if(b.dataset.action==='complete'){const next=!done(en);en.checkpoints.forEach(p=>p.done=next);en.status=next?'done':'planned'}if(b.dataset.action==='missed'){en.status=en.status==='missed'?'planned':'missed';en.checkpoints.forEach(p=>p.done=false)}if(b.dataset.action==='remove-check'){en.checkpoints=en.checkpoints.filter(p=>p.id!==b.dataset.check);en.status='planned'}if(b.dataset.action==='remove-entry')ensureDay(selected).entries=ensureDay(selected).entries.filter(x=>x.id!==en.id)})}});
$('#export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='ritim-yedek-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};render();

function updateThemeButton(){const dark=document.documentElement.dataset.theme==='dark';$('#themeToggle').textContent=dark?'☀':'☾';$('#themeToggle').setAttribute('aria-label',dark?'Açık temaya geç':'Karanlık temaya geç');$('#themeToggle').setAttribute('aria-pressed',String(dark));const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.content=dark?'#181818':'#285b49'}
$('#themeToggle').onclick=()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('ritim-theme',theme)}catch{}updateThemeButton()};updateThemeButton();








